@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Spectral:wght@400;500;600;700&display=swap');
:root{--ink:#1d2b24;--ink-2:#32443a;--green:#4c664d;--green-light:#e4eadf;--gold:#bd9152;--gold-light:#f2e7d2;--paper:#f5f2e9;--paper-2:#ebe6d9;--muted:#888b7d;--line:#e4dfd2;--white:#fffdf8;--red:#a75441;--shadow:0 12px 40px rgba(39,44,32,.08)}
*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font-family:'DM Sans',sans-serif;font-size:14px}button,input,textarea,select{font:inherit}button{cursor:pointer}.app-shell{min-height:100vh;display:flex}.rail{width:88px;background:var(--ink);display:flex;flex-direction:column;align-items:center;color:#e9e5d7;padding:23px 10px 18px;position:fixed;inset:0 auto 0 0;z-index:5}.brand-mark{width:48px;height:48px;display:grid;place-items:center;text-decoration:none;color:#f0d7a2;background:#2c4033;border:1px solid rgba(202,167,105,.55);border-radius:15px;box-shadow:inset 0 0 0 4px rgba(202,167,105,.08);font-size:25px}.brand-icon{transform:rotate(45deg)}.rail-divider{height:1px;width:40px;background:#465348;margin:23px 0 19px}.rail-nav,.rail-bottom{display:flex;flex-direction:column;gap:12px;width:100%;align-items:center}.rail-link{border:0;background:none;color:#9da99c;width:64px;height:60px;border-radius:12px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:4px;transition:.2s}.rail-link span{font-size:21px;line-height:21px}.rail-link small{font-size:10px;letter-spacing:.02em}.rail-link:hover,.rail-link.active{background:#304237;color:#f2d69f}.rail-bottom{margin-top:auto}.online-dot{width:8px;height:8px;background:#81b27e;border-radius:50%;box-shadow:0 0 0 5px rgba(129,178,126,.13);margin-bottom:15px}.main-area{margin-left:88px;width:calc(100% - 88px);min-height:100vh;display:flex;flex-direction:column}.topbar{height:72px;display:flex;align-items:center;justify-content:space-between;padding:0 clamp(22px,4vw,62px);border-bottom:1px solid var(--line);background:rgba(249,247,240,.9)}.realm-label{display:flex;align-items:center;gap:11px;color:#727769;font-size:10px;letter-spacing:.15em;font-weight:700}.realm-label i{height:16px;width:1px;background:#d3cebf;margin:0 3px}.tiny-crest{color:var(--gold);font-size:16px}.season-label{color:#a3977e;font-weight:500}.top-actions{display:flex;align-items:center;gap:22px}.server-status{font-size:11px;color:#797e71}.server-status b{color:#c1bba9;padding:0 4px}.status-pulse{display:inline-block;width:7px;height:7px;border-radius:50%;background:#75a278;margin-right:6px;box-shadow:0 0 0 3px #e2eadf}.icon-button{width:36px;height:36px;border:1px solid var(--line);border-radius:50%;background:var(--white);font-size:20px;color:#64705f;position:relative}.notification-dot{position:absolute;width:6px;height:6px;background:#c87c59;border-radius:50%;right:7px;top:7px}.user-chip{border:0;background:none;display:flex;align-items:center;gap:9px;color:var(--ink);font-weight:600}.user-avatar{width:31px;height:31px;border-radius:50%;background:#e5cda5;color:#644f32;display:grid;place-items:center;font-family:'Spectral',serif;font-size:16px}.chevron{color:#a6a090;font-size:16px}.view-root{width:min(1360px,100%);margin:0 auto;padding:32px clamp(22px,4vw,62px) 25px;flex:1}.site-footer{padding:10px 4vw 18px;text-align:center;color:#999687;font-size:10px;letter-spacing:.04em}.site-footer>span:first-child{color:var(--gold)}.footer-sep{margin:0 7px;color:#c5bda9}.footer-version{float:right;color:#b1ad9f}
/* home dashboard */
.welcome-row{display:flex;justify-content:space-between;align-items:flex-end;margin-bottom:23px}.eyebrow{font-size:10px;letter-spacing:.18em;text-transform:uppercase;color:#9a845e;font-weight:700}.welcome-row h1,.page-heading h1{font:600 31px/1.1 'Spectral',serif;margin:6px 0 0;letter-spacing:-.02em}.welcome-row h1 span{color:#9e8256}.date-note{font-size:12px;color:#929184;margin-top:8px}.weather-chip{display:flex;align-items:center;gap:9px;color:#727467;font-size:11px;border:1px solid var(--line);background:#faf8f1;border-radius:30px;padding:8px 13px}.weather-chip b{color:#4d594a;font-weight:600}.weather-icon{font-size:18px;color:#ba975b}.dashboard-grid{display:grid;grid-template-columns:minmax(0,1.8fr) minmax(270px,.92fr);gap:20px;align-items:start}.left-column,.right-column{display:flex;flex-direction:column;gap:19px}.hero-card{height:270px;border-radius:17px;overflow:hidden;position:relative;background:#35463c;box-shadow:var(--shadow);color:white}.hero-art{position:absolute;inset:0;width:100%;height:100%;object-fit:cover}.hero-card:after{content:'';position:absolute;inset:0;background:linear-gradient(90deg,rgba(18,34,27,.83) 0%,rgba(24,41,31,.65) 35%,rgba(27,39,30,.08) 78%),linear-gradient(0deg,rgba(22,35,27,.33),transparent 40%)}.hero-content{position:absolute;z-index:1;left:30px;top:28px;max-width:330px}.location-tag{font-size:9px;letter-spacing:.17em;font-weight:700;color:#e8c990}.hero-content h2{font:600 29px/1.08 'Spectral',serif;margin:10px 0 8px}.hero-content p{color:#e5e3d8;line-height:1.55;font-size:11px;margin:0;max-width:280px}.hero-meta{display:flex;gap:17px;margin-top:17px;font-size:10px;color:#dfdbca}.hero-meta span{display:flex;align-items:center;gap:5px}.hero-meta strong{font-weight:600;color:#f0d8a8}.hero-bottom{position:absolute;z-index:1;bottom:15px;left:30px;right:20px;display:flex;justify-content:space-between;align-items:center}.weather-place{font-size:10px;color:#e0e0d4}.weather-place b{font-weight:600;color:white}.button-primary,.button-outline,.button-quiet{border:0;border-radius:7px;padding:10px 15px;font-size:11px;font-weight:700;transition:.18s}.button-primary{background:var(--green);color:white;box-shadow:0 4px 10px rgba(33,50,37,.12)}.button-primary:hover{background:#3e5841;transform:translateY(-1px)}.hero-bottom .button-primary{background:#e0c28e;color:#25332a;padding:9px 14px}.hero-bottom .button-primary:hover{background:#f0d5a5}.button-outline{background:#faf8f1;border:1px solid var(--line);color:#586252}.button-outline:hover{border-color:#b7aa8c;background:#fff}.button-quiet{background:none;color:#8a7959;padding:7px 8px}.button-quiet:hover{background:#f5f0e5}.section-heading{display:flex;justify-content:space-between;align-items:center;margin-bottom:11px}.section-heading h3{margin:0;font:600 17px 'Spectral',serif}.section-heading .subheading{font-size:10px;color:#929184;margin-top:3px}.text-link{border:0;background:none;color:#8e754e;font-size:10px;font-weight:700}.quest-list{display:flex;flex-direction:column;gap:9px}.quest-card{display:flex;align-items:center;gap:13px;border:1px solid var(--line);background:rgba(255,253,248,.72);padding:12px;border-radius:11px;transition:.16s}.quest-card:hover{border-color:#cfc3a9;transform:translateY(-1px)}.quest-glyph{height:40px;width:40px;border-radius:10px;background:#eceddf;display:grid;place-items:center;color:#687b5d;font-size:20px;flex:none}.quest-glyph.gold{background:#f2e7d2;color:#ad8450}.quest-copy{min-width:0;flex:1}.quest-copy h4{margin:0 0 4px;font:600 13px 'Spectral',serif}.quest-copy p{font-size:10px;color:#898b7d;margin:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.quest-reward{font-size:10px;color:#947541;text-align:right;white-space:nowrap;line-height:1.55}.quest-reward b{font-size:11px}.quest-action{height:30px;width:31px;border:1px solid #e1dccf;border-radius:7px;background:#fffdf8;color:#738067;font-size:16px}.quest-action:hover{background:#e7eddf}.card{background:rgba(255,253,248,.78);border:1px solid var(--line);border-radius:13px;padding:17px}.profile-card{padding:0;overflow:hidden}.profile-banner{height:57px;background:linear-gradient(110deg,#3b5140,#657157);position:relative}.profile-banner:after{content:'✦';position:absolute;right:21px;top:4px;color:rgba(237,213,167,.3);font-size:45px}.profile-main{padding:0 17px 16px}.profile-identity{display:flex;align-items:flex-end;gap:10px;margin-top:-22px;position:relative}.portrait{width:48px;height:48px;border-radius:12px;border:3px solid #fffdf8;background:#d9bd8a;color:#594d35;display:grid;place-items:center;font:700 23px 'Spectral',serif}.profile-name{font:600 18px 'Spectral',serif;margin-bottom:2px}.profile-class{font-size:10px;color:#858679}.edit-button{margin-left:auto;border:1px solid var(--line);background:#fffdf8;border-radius:7px;padding:6px 9px;color:#76786d;font-size:10px}.rank-row{display:flex;justify-content:space-between;margin-top:17px;font-size:10px;color:#777a6e}.rank-row strong{color:#4c604c}.xp-track{height:5px;border-radius:5px;background:#e8e4d8;margin-top:8px;overflow:hidden}.xp-fill{height:100%;width:38%;background:#809273;border-radius:5px;transition:width .3s}.profile-stats{display:grid;grid-template-columns:repeat(3,1fr);margin-top:14px;border-top:1px solid var(--line);padding-top:12px}.stat{text-align:center;border-right:1px solid var(--line)}.stat:last-child{border:0}.stat strong{font:600 15px 'Spectral',serif;display:block}.stat span{font-size:9px;color:#8c8d80}.currency-row{display:flex;gap:7px;margin-top:12px}.currency{flex:1;border-radius:7px;background:#f4efe4;padding:7px 8px;display:flex;justify-content:center;align-items:center;gap:5px;color:#796444;font-size:10px}.currency b{color:#514630}.guild-mini{display:flex;align-items:center;gap:11px}.guild-emblem{width:42px;height:42px;border-radius:11px;background:#e9e4d4;display:grid;place-items:center;color:#71806a;font-size:21px}.guild-info{flex:1}.guild-info strong{display:block;font:600 14px 'Spectral',serif}.guild-info span{font-size:10px;color:#929184}.guild-card-small .section-heading{margin-bottom:12px}.guild-footer{border-top:1px solid var(--line);margin-top:13px;padding-top:11px;display:flex;justify-content:space-between;color:#87887c;font-size:10px}.guild-footer b{color:#63745b}.people-card{padding-bottom:13px}.people-list{display:flex;flex-direction:column;gap:10px}.person-row{display:flex;align-items:center;gap:9px}.person-avatar{width:30px;height:30px;border-radius:50%;display:grid;place-items:center;font:600 12px 'Spectral',serif;color:#5a5746;position:relative}.person-avatar.online:after{content:'';position:absolute;width:7px;height:7px;right:-1px;bottom:0;border:2px solid #fffdf8;border-radius:50%;background:#78a37a}.person-info{flex:1}.person-info strong{font-size:10px;display:block;font-weight:600}.person-info span{display:block;font-size:9px;color:#939285;margin-top:2px}.person-status{font-size:9px;color:#7a8a6c}.presence-note{font-size:9px;color:#aaa798;border-top:1px solid var(--line);padding-top:9px;margin-top:12px}.chat-card{padding:0;overflow:hidden}.chat-head{padding:14px 16px 11px;display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid var(--line)}.chat-head h3{margin:0;font:600 16px 'Spectral',serif}.chat-head span{font-size:9px;color:#909181}.chat-feed{padding:12px 15px 4px;max-height:210px;overflow:auto;display:flex;flex-direction:column;gap:11px}.chat-line{display:flex;gap:9px;align-items:flex-start}.chat-line .person-avatar{width:25px;height:25px;flex:none}.chat-message{min-width:0;line-height:1.4;font-size:10px;color:#64685e}.chat-message strong{font-size:10px;color:#374338;margin-right:4px}.chat-message em{font-size:9px;color:#aaa28e;font-style:normal}.chat-input-row{display:flex;gap:7px;padding:10px 12px;border-top:1px solid var(--line)}.chat-input-row input{min-width:0;flex:1;border:1px solid #e8e2d6;background:#fbfaf5;border-radius:7px;padding:9px 10px;font-size:10px;outline:none}.chat-input-row input:focus{border-color:#99a68d}.send-button{width:34px;border:0;border-radius:7px;background:#526a53;color:white;font-size:15px}.chat-tabs{display:flex;gap:10px}.chat-tabs button{border:0;background:none;color:#969487;font-size:9px;padding:0}.chat-tabs button.selected{color:#687e5f;font-weight:700}
/* secondary views */
.page-heading{display:flex;justify-content:space-between;align-items:flex-end;margin-bottom:23px}.page-heading p{margin:8px 0 0;color:#848679;font-size:12px}.subnav{display:flex;gap:8px;margin-bottom:19px}.pill-tab{border:1px solid var(--line);background:#faf8f1;color:#797a6d;border-radius:20px;padding:8px 14px;font-size:10px}.pill-tab.selected{background:#405843;border-color:#405843;color:#fff}.guild-hero{background:linear-gradient(115deg,#314638,#607159);color:white;border-radius:15px;padding:24px;display:flex;align-items:center;gap:18px;margin-bottom:18px}.guild-hero .guild-emblem{background:rgba(255,255,255,.13);color:#f0d6a0;width:58px;height:58px;font-size:28px}.guild-hero h2{font:600 25px 'Spectral',serif;margin:0 0 4px}.guild-hero p{margin:0;color:#d4d9ca;font-size:11px}.guild-hero .button-outline{margin-left:auto;background:#f5efdf;border:0}.content-grid{display:grid;grid-template-columns:1.35fr 1fr;gap:18px}.data-list{display:flex;flex-direction:column}.data-row{display:flex;align-items:center;gap:12px;padding:12px 0;border-bottom:1px solid var(--line)}.data-row:last-child{border:0}.data-row .person-avatar{width:35px;height:35px}.data-row-main{flex:1}.data-row-main strong{display:block;font-size:11px}.data-row-main span{font-size:10px;color:#8e8f82}.rank-tag,.role-tag{font-size:9px;color:#8d724c;background:#f2e9d8;padding:5px 8px;border-radius:15px}.city-banner{height:200px;border-radius:15px;background:linear-gradient(120deg,#304538,#71836b);position:relative;color:white;overflow:hidden;padding:24px 28px;margin-bottom:18px}.city-banner:after{content:'♜';position:absolute;right:10%;top:-50px;font-size:245px;color:rgba(235,219,179,.12)}.city-banner h2{font:600 30px 'Spectral',serif;margin:3px 0}.city-banner p{color:#e0e4d6;font-size:11px;max-width:300px;line-height:1.5}.mayor-row{display:flex;align-items:center;gap:11px}.mayor-row .person-avatar{width:37px;height:37px}.mayor-row strong{font-size:11px}.mayor-row span{display:block;font-size:9px;color:#909285;margin-top:3px}.position-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:10px}.position-tile{background:#f9f7f0;border:1px solid var(--line);border-radius:9px;padding:12px}.position-tile span{font-size:17px;color:#a08458}.position-tile strong{display:block;font:600 13px 'Spectral',serif;margin:6px 0 3px}.position-tile small{font-size:9px;color:#909184}.journal-layout{display:grid;grid-template-columns:1.45fr 1fr;gap:18px}.journal-entry{border-left:2px solid #c4a878;padding:1px 0 17px 17px;position:relative}.journal-entry:before{content:'';position:absolute;width:7px;height:7px;border-radius:50%;background:#c2a16a;left:-4.5px;top:4px}.journal-entry:last-child{padding-bottom:0}.journal-entry time{font-size:9px;letter-spacing:.09em;color:#9b8967;text-transform:uppercase}.journal-entry h4{font:600 16px 'Spectral',serif;margin:4px 0}.journal-entry p{margin:0;color:#818376;font-size:10px;line-height:1.55}.empty-state{text-align:center;padding:35px 20px;color:#88897c}.empty-state span{font-size:27px;color:#ba9b69}.empty-state h3{font:600 18px 'Spectral',serif;color:#3b4a3e;margin:8px 0}.empty-state p{font-size:11px;line-height:1.5;max-width:300px;margin:0 auto 15px}.modal-layer{position:fixed;inset:0;z-index:20;background:rgba(20,30,24,.56);display:grid;place-items:center;padding:18px}.modal-layer[hidden]{display:none}.modal{width:min(460px,100%);background:var(--paper);border:1px solid rgba(217,203,177,.8);border-radius:16px;padding:22px;box-shadow:0 24px 80px rgba(0,0,0,.24);max-height:90vh;overflow:auto}.modal-head{display:flex;align-items:flex-start;justify-content:space-between;margin-bottom:17px}.modal-head h2{font:600 23px 'Spectral',serif;margin:0}.modal-head p{font-size:10px;color:#8d8d80;margin:5px 0 0}.close-modal{width:30px;height:30px;border:1px solid var(--line);background:#fffdf8;border-radius:50%;color:#76776c}.form-label{display:block;font-size:10px;font-weight:700;color:#697163;margin:13px 0 6px}.form-control{width:100%;border:1px solid #ddd7ca;border-radius:7px;padding:10px;background:#fffdf8;color:#334238;outline:none;font-size:11px}.form-control:focus{border-color:#8b9b81}.class-options{display:grid;grid-template-columns:repeat(3,1fr);gap:7px}.class-option{border:1px solid var(--line);background:#fbfaf5;border-radius:8px;padding:9px 5px;text-align:center;color:#60695e;font-size:10px}.class-option span{display:block;font-size:18px;margin-bottom:4px}.class-option.selected{border-color:#778c70;background:#eaf0e6;color:#415c43}.modal-actions{display:flex;justify-content:flex-end;gap:8px;margin-top:19px}.toast-stack{position:fixed;right:22px;bottom:22px;z-index:30;display:flex;flex-direction:column;gap:8px}.toast{background:#273a2e;color:#f5eedf;padding:12px 16px;border-radius:9px;box-shadow:var(--shadow);font-size:11px;animation:toastIn .25s ease}.toast b{color:#e1c38f}@keyframes toastIn{from{transform:translateY(8px);opacity:0}to{transform:translateY(0);opacity:1}}
