@media(max-width:760px){.rail{width:64px;padding:16px 5px}.brand-mark{width:42px;height:42px}.rail-link{width:54px}.main-area{margin-left:64px;width:calc(100% - 64px)}.topbar{height:60px;padding:0 16px}.realm-label{font-size:9px;gap:7px}.season-label,.realm-label i{display:none}.top-actions{gap:10px}.user-chip{gap:6px}.view-root{padding:22px 16px}.dashboard-grid{grid-template-columns:1fr}.right-column{display:grid;grid-template-columns:1fr 1fr;align-items:start}.profile-card{grid-column:span 2}.chat-card{grid-column:1/-1}.welcome-row h1,.page-heading h1{font-size:27px}.hero-card{height:255px}.content-grid,.journal-layout{grid-template-columns:1fr}}
