const SAVE_KEY = 'hearthvale-save-v1';
const defaultState = {
  name:'Mira', className:'Ranger', bio:'A quiet pathfinder with a soft spot for lost causes.', level:3, xp:72, gold:145, silver:28, influence:12,
  guild:'The Lantern Wardens', guildRole:'Wayfinder', city:'Alderbrook', voted:false, selectedMayor:'', role:'Citizen',
  completed:[], messages:[], journal:[{title:'A new leaf',text:'You arrived in Hearthvale with a weathered map and a promise to make your own story.',when:'Today'}],
  tab:'home'
};
let state = loadState();
const roster = [
  {name:'Thorne',role:'Guildmaster',className:'Paladin',color:'#d8c6a5',icon:'T',online:true},
  {name:'Liora',role:'Lorekeeper',className:'Bard',color:'#d8c4d6',icon:'L',online:true},
  {name:'Bramble',role:'Warden',className:'Druid',color:'#bfd1b8',icon:'B',online:false},
  {name:'Mira',role:'Wayfinder',className:'Ranger',color:'#e4cda2',icon:'M',online:true}
];
const visitors = [
  {name:'Elowen',role:'Bard · wandering minstrel',color:'#e6c6d5',icon:'E',online:true,status:'Sharing a song at the inn'},
  {name:'Kael',role:'Knight · Dawnwatch',color:'#c6d0dd',icon:'K',online:true,status:'On the north road'},
  {name:'Sable',role:'Alchemist · Free agent',color:'#d1c9a7',icon:'S',online:false,status:'Last seen 2h ago'}
];
const quests = [
  {id:'herbs',title:'A handful of moonmint',text:'Old Nessa needs a fresh bundle before sundown.',icon:'❋',gold:35,xp:25,kind:'gold'},
  {id:'bridge',title:'The bridge at Briar Run',text:'A traveler is waiting on the far side of the creek.',icon:'⌁',gold:50,xp:35,kind:''},
  {id:'notice',title:'A note for the watch',text:'Deliver a sealed letter to Captain Rowan.',icon:'✉',gold:25,xp:20,kind:'gold'}
];
const candidates = [
  {name:'Mara Vell',role:'Current mayor · Hearthkeeper',icon:'M',color:'#d7c6a2',pledge:'Keep the river road open and fund the spring market.'},
  {name:'Tomas Reed',role:'Guild artisan · Freefolk',icon:'T',color:'#c7d4be',pledge:'A public workshop and fairer stall fees for every craft.'},
  {name:'You',role:'Candidate · ' + (state.role || 'Citizen'),icon:'Y',color:'#e0c58f',pledge:'A town where every traveler has a place at the table.'}
];
function loadState(){try{return {...defaultState,...JSON.parse(localStorage.getItem(SAVE_KEY)||'{}')}}catch{return {...defaultState}}}
function save(){localStorage.setItem(SAVE_KEY,JSON.stringify(state));updateTop()}
function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function updateTop(){document.getElementById('top-name').textContent=state.name;document.getElementById('top-avatar').textContent=(state.name[0]||'M').toUpperCase();document.getElementById('online-count').textContent=128+Math.floor(Math.random()*4)}
function avatar(name,color,online=false){return `<span class="person-avatar ${online?'online':''}" style="background:${color}">${esc(name[0])}</span>`}
function heroArt(){return `<svg class="hero-art" viewBox="0 0 1000 500" preserveAspectRatio="xMidYMid slice" xmlns="http://www.w3.org/2000/svg"><defs><linearGradient id="sky" x2="0" y2="1"><stop stop-color="#8d9c89"/><stop offset=".52" stop-color="#d2aa78"/><stop offset="1" stop-color="#596c56"/></linearGradient><linearGradient id="hill" x2="0" y2="1"><stop stop-color="#72856a"/><stop offset="1" stop-color="#334a3a"/></linearGradient></defs><rect width="1000" height="500" fill="url(#sky)"/><circle cx="744" cy="112" r="53" fill="#f2d89e" opacity=".8"/><path d="M0 245 118 130l85 92 116-137 112 131 103-90 130 106 103-132 136 144 97-86v342H0Z" fill="#778772" opacity=".75"/><path d="m0 289 140-91 133 74 117-102 171 122 122-92 123 67 95-95 99 84v244H0Z" fill="url(#hill)"/><path d="M0 335q188-55 368-2t337-10q164-53 295 8v169H0Z" fill="#425b42"/><path d="M0 393q172-68 347-5t344-19q161-49 309-6v137H0Z" fill="#2e4738"/><path d="M540 500q-29-85-7-125t-4-70q66 45 39 100t43 95" fill="#799275" opacity=".7"/><g fill="#d4c29d" stroke="#544f3f" stroke-width="3"><path d="M625 320h62v75h-62z"/><path d="m615 321 41-36 45 36Z"/><path d="M699 336h70v77h-70z"/><path d="m690 337 44-39 45 39Z"/><path d="M774 311h48v83h-48z"/><path d="m768 312 30-36 31 36Z"/><path d="M856 339h53v70h-53z"/><path d="m849 340 34-33 34 33Z"/></g><g fill="#534b3a"><path d="M648 351h14v22h-14zM719 363h14v21h-14zM789 335h12v20h-12zM875 360h13v20h-13z"/></g><g fill="#e6c984"><path d="M594 389h20v7h-20zM677 401h18v7h-18zM760 402h18v7h-18zM830 388h22v7h-22z"/></g><g fill="#283d32"><path d="M52 398q17-90 35 0m-55 8q28-133 53 0m800 9q20-92 38 0m-11 0q25-140 55 0m-19 0q31-107 49 0"/></g><path d="M0 448q198-29 367 5t329-3q183-39 304 2v48H0Z" fill="#263a30"/></svg>`}
function progress(){const threshold=100;return Math.min(100,(state.xp/threshold)*100)}
function render(){updateTop();const root=document.getElementById('view-root');root.innerHTML=state.tab==='home'?renderHome():state.tab==='guild'?renderGuild():state.tab==='city'?renderCity():renderJournal();document.querySelectorAll('.rail-link[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===state.tab));bindChat();}
function renderHome(){const active=quests.filter(q=>!state.completed.includes(q.id));return `<div class="welcome-row"><div><div class="eyebrow">A living realm, waiting for you</div><h1>Good day, <span>${esc(state.name)}</span></h1><div class="date-note">The 14th day of Emberfall <span>·</span> A quiet afternoon in Alderbrook</div></div><div class="weather-chip"><span class="weather-icon">☼</span><span><b>Clear skies</b> · 18°C</span></div></div><div class="dashboard-grid"><div class="left-column"><section class="hero-card">${heroArt()}<div class="hero-content"><div class="location-tag">✦ &nbsp;YOUR CURRENT HAVEN</div><h2>Alderbrook</h2><p>A riverside town of mossy stone, warm hearths, and stories still being written.</p><div class="hero-meta"><span>♜ <strong>Mayor</strong> Mara Vell</span><span>♧ <strong>Peaceful</strong> district</span></div></div><div class="hero-bottom"><span class="weather-place">⌖ &nbsp; <b>Greenward Valley</b> &nbsp;·&nbsp; Heartlands</span><button class="button-primary" data-action="explore">Explore town&nbsp; ↗</button></div></section><section><div class="section-heading"><div><h3>Town board</h3><div class="subheading">A few ways to lend a hand today</div></div><button class="text-link" data-view="journal">YOUR JOURNAL&nbsp; →</button></div><div class="quest-list">${active.length?active.map(q=>`<article class="quest-card"><div class="quest-glyph ${q.kind}">${q.icon}</div><div class="quest-copy"><h4>${q.title}</h4><p>${q.text}</p></div><div class="quest-reward"><b>+${q.gold}g</b><br>+${q.xp} XP</div><button class="quest-action" data-quest="${q.id}" title="Complete quest">↗</button></article>`).join(''):`<div class="card empty-state"><span>✦</span><h3>All caught up</h3><p>The townsfolk are grateful. Take a moment to wander or share a story.</p><button class="button-outline" data-action="explore">Wander the town</button></div>`}</div></section><section class="card chat-card"><div class="chat-head"><div><h3>Common room</h3><span>Roleplay with travelers in Alderbrook</span></div><div class="chat-tabs"><button class="selected">LOCAL</button><button data-action="chat-help">GUIDELINES</button></div></div><div class="chat-feed" id="chat-feed">${renderMessages()}</div><form class="chat-input-row" id="chat-form"><input name="message" maxlength="180" autocomplete="off" placeholder="Say something in character…" aria-label="Roleplay message"><button class="send-button" aria-label="Send message">➤</button></form></section></div><div class="right-column"><section class="card profile-card"><div class="profile-banner"></div><div class="profile-main"><div class="profile-identity"><div class="portrait">${esc((state.name[0]||'M').toUpperCase())}</div><div><div class="profile-name">${esc(state.name)}</div><div class="profile-class">Level ${state.level} ${esc(state.className)} · ${esc(state.role)}</div></div><button class="edit-button" data-action="profile">Edit</button></div><div class="rank-row"><span>RANK &nbsp;<strong>${rankName()}</strong></span><span>${state.xp}/100 XP</span></div><div class="xp-track"><div class="xp-fill" style="width:${progress()}%"></div></div><div class="profile-stats"><div class="stat"><strong>${state.influence}</strong><span>Influence</span></div><div class="stat"><strong>${state.completed.length}</strong><span>Quests</span></div><div class="stat"><strong>${state.level}</strong><span>Level</span></div></div><div class="currency-row"><div class="currency">◉ <b>${state.gold}</b> gold</div><div class="currency">◇ <b>${state.silver}</b> silver</div></div></div></section><section class="card guild-card-small"><div class="section-heading"><div><h3>Your guild</h3><div class="subheading">The circle that has your back</div></div><button class="text-link" data-view="guild">OPEN →</button></div><div class="guild-mini"><div class="guild-emblem">⚒</div><div class="guild-info"><strong>${esc(state.guild||'Unaffiliated')}</strong><span>${esc(state.guildRole||'Free adventurer')} · ${state.guild?'12 members':'Find your people'}</span></div></div><div class="guild-footer"><span>Guild card <b>● Active</b></span><span>Rank ${state.level>5?'II':'I'}</span></div></section><section class="card people-card"><div class="section-heading"><div><h3>Nearby souls</h3><div class="subheading">Sharing this corner of the realm</div></div><span class="person-status">● LIVE</span></div><div class="people-list">${visitors.map(v=>`<div class="person-row">${avatar(v.name,v.color,v.online)}<div class="person-info"><strong>${v.name}</strong><span>${v.status}</span></div></div>`).join('')}</div><div class="presence-note">Presence is a glimpse of fellow adventurers' stories.</div></section></div></div>`}
function rankName(){return state.level>=8?'Silverleaf':state.level>=5?'Pathfinder':state.level>=3?'Wayfarer':'Newcomer'}
function defaultMessages(){return [{name:'Liora',color:'#d8c4d6',text:'The river mist made the old bridge look enchanted this morning.',time:'2m ago'},{name:'Thorne',color:'#d8c6a5',text:'If anyone is heading north, I could use another set of eyes.',time:'5m ago'},{name:'Elowen',color:'#e6c6d5',text:'I have a new song for the inn tonight. All are welcome ✨',time:'8m ago'}]}
function renderMessages(){const list=state.messages.length?state.messages:defaultMessages();return list.map(m=>`<div class="chat-line">${avatar(m.name,m.color||'#d8c6a5')}<div class="chat-message"><strong>${esc(m.name)}</strong><em>${esc(m.time||'now')}</em><div>${esc(m.text)}</div></div></div>`).join('')}

input.newString:
function renderMessages(){const list=state.messages.length?state.messages:defaultMessages();return list.map(m=>`<div class="chat-line">${avatar(m.name,m.color||'#d8c6a5')}<div class="chat-message"><strong>${esc(m.name)}</strong><em>${esc(m.time||'now')}</em><div>${esc(m.text)}</div></div></div>`).join('')}
function renderGuild(){const members=roster.map(p=>`<div class="data-row">${avatar(p.name,p.color,p.online)}<div class="data-row-main"><strong>${p.name}${p.name===state.name?' (you)':''}</strong><span>${p.className} · ${p.online?'In Alderbrook':'Away'}</span></div><span class="rank-tag">${p.name===state.name?esc(state.guildRole):p.role}</span></div>`).join('');return `<div class="page-heading"><div><div class="eyebrow">Find your fellowship</div><h1>Guild hall</h1><p>Good company makes every road shorter.</p></div><button class="button-primary" data-action="guild-card">✦ &nbsp;Guild card</button></div>${state.guild?`<section class="guild-hero"><div class="guild-emblem">⚒</div><div><div class="eyebrow" style="color:#e2c992">YOUR FELLOWSHIP · EST. 104</div><h2>${esc(state.guild)}</h2><p>Keep a lantern lit for every traveler on the road home.</p></div><button class="button-outline" data-action="guild-card">View guild card &nbsp; ↗</button></section>`:`<section class="guild-hero"><div class="guild-emblem">✦</div><div><div class="eyebrow" style="color:#e2c992">YOUR NEXT CHAPTER</div><h2>Find your fellowship</h2><p>Join a guild or gather friends to make your own mark.</p></div><button class="button-outline" data-action="guild-join">Browse guilds &nbsp; ↗</button></section>`}<div class="subnav"><button class="pill-tab selected">Overview</button><button class="pill-tab" data-action="guild-card">Guild card</button><button class="pill-tab" data-action="guild-join">${state.guild?'Find another guild':'Browse guilds'}</button></div><div class="content-grid"><section class="card"><div class="section-heading"><div><h3>Fellow travelers</h3><div class="subheading">A few of the folks keeping the lanterns lit</div></div><span class="person-status">${state.guild?'12 MEMBERS':'OPEN TO ALL'}</span></div><div class="data-list">${members}</div><div class="guild-footer"><span>Ranks are earned through kindness and shared adventures.</span></div></section><section class="card"><div class="section-heading"><div><h3>Standing & ranks</h3><div class="subheading">Your guild card grows with your story</div></div></div><div class="position-grid"><div class="position-tile"><span>✦</span><strong>${rankName()}</strong><small>Current realm rank</small></div><div class="position-tile"><span>⚒</span><strong>${state.guildRole||'Free agent'}</strong><small>Guild standing</small></div><div class="position-tile"><span>◉</span><strong>${state.influence} renown</strong><small>Town influence</small></div><div class="position-tile"><span>♧</span><strong>${state.completed.length} deeds</strong><small>Recorded in journal</small></div></div><div style="margin-top:16px"><button class="button-outline" data-action="guild-join">${state.guild?'Browse other guilds':'Find your guild'}</button></div></section></div>`}
function renderCity(){return `<div class="page-heading"><div><div class="eyebrow">Alderbrook · Greenward Valley</div><h1>City hall</h1><p>Small choices shape the place we call home.</p></div><button class="button-outline" data-action="volunteer">♡ &nbsp;Volunteer</button></div><section class="city-banner"><div class="eyebrow" style="color:#e5ca95">✦ &nbsp;A FRIENDLY PLACE BY THE RIVER</div><h2>Alderbrook</h2><p>Known for its spring market, open doors, and the old bridge that has outlasted three mayors.</p><div class="mayor-row">${avatar('Mara','#d7c6a2')}<div><strong>Mara Vell</strong><span>Mayor · Hearthkeeper · Term ends in 18 days</span></div></div></section><div class="content-grid"><section class="card"><div class="section-heading"><div><h3>Election day is coming</h3><div class="subheading">Choose the future you want to share</div></div><span class="role-tag">${state.voted?'BALLOT CAST':'18 DAYS LEFT'}</span></div><div class="data-list">${candidates.slice(0,2).map((c,i)=>`<div class="data-row">${avatar(c.name,c.color)}<div class="data-row-main"><strong>${c.name}</strong><span>${c.pledge}</span></div><button class="button-outline" data-vote="${i}" ${state.voted?'disabled':''}>${state.selectedMayor===c.name?'✓ Voted':state.voted?'Vote':'Vote'}</button></div>`).join('')}</div>${state.voted?`<div class="guild-footer"><span>Your ballot is sealed. Thank you for taking part.</span></div>`:`<div class="guild-footer"><span>One vote per adventurer · Your choice stays private.</span><button class="text-link" data-action="run-candidate">RUN FOR MAYOR</button></div>`}</section><section class="card"><div class="section-heading"><div><h3>Town positions</h3><div class="subheading">Every role has room for a new voice</div></div></div><div class="position-grid"><div class="position-tile"><span>♜</span><strong>Town mayor</strong><small>Elected · Mara Vell</small></div><div class="position-tile"><span>⚖</span><strong>River warden</strong><small>Open volunteer role</small></div><div class="position-tile"><span>✧</span><strong>Market steward</strong><small>Appointed by the council</small></div><div class="position-tile"><span>♧</span><strong>Storykeeper</strong><small>Open to all storytellers</small></div></div><div style="margin-top:14px"><button class="button-outline" data-action="volunteer">Ask about a position</button></div></section></div><div style="height:16px"></div><section class="card"><div class="section-heading"><div><h3>Local noticeboard</h3><div class="subheading">A note from your neighbors</div></div><span class="person-status">UPDATED TODAY</span></div><div class="quest-card" style="background:transparent"><div class="quest-glyph gold">♧</div><div class="quest-copy"><h4>Spring market helpers wanted</h4><p>Help the stallholders set up and share a little good cheer. Ask at the town hall.</p></div><button class="button-outline" data-action="volunteer">Offer a hand</button></div></section>`}
function renderJournal(){const deeds=[...state.journal];if(state.completed.length)quests.filter(q=>state.completed.includes(q.id)).forEach(q=>deeds.unshift({title:q.title,text:`You helped a neighbor and earned ${q.gold} gold and ${q.xp} experience.`,when:'Today'}));return `<div class="page-heading"><div><div class="eyebrow">The story so far</div><h1>Adventurer's journal</h1><p>Little moments have a way of becoming legends.</p></div><button class="button-outline" data-view="home">← &nbsp;Back to realm</button></div><div class="journal-layout"><section class="card"><div class="section-heading"><div><h3>Recent chapters</h3><div class="subheading">Your deeds and days in Hearthvale</div></div></div>${deeds.map(d=>`<article class="journal-entry"><time>${esc(d.when)}</time><h4>${esc(d.title)}</h4><p>${esc(d.text)}</p></article>`).join('')}</section><section class="card"><div class="section-heading"><div><h3>Adventurer card</h3><div class="subheading">Your name travels with you</div></div><button class="text-link" data-action="profile">EDIT</button></div><div class="guild-hero" style="margin:0;padding:16px;background:linear-gradient(120deg,#425a45,#728369)"><div class="portrait">${esc((state.name[0]||'M').toUpperCase())}</div><div><div class="eyebrow" style="color:#e3cb9c">${esc(state.city)} RESIDENT</div><h2 style="font-size:20px">${esc(state.name)}</h2><p>Level ${state.level} ${esc(state.className)}</p></div></div><p style="font-size:11px;line-height:1.6;color:#7f8175;margin:14px 0">${esc(state.bio)}</p><div class="guild-footer"><span>Rank <b>${rankName()}</b></span><span>${state.influence} influence</span></div></section></div>`}

