function renderJournal(){const deeds=[...state.journal];if(state.completed.length)quests.filter(q=>state.completed.includes(q.id)).forEach(q=>deeds.unshift({title:q.title,text:`You helped a neighbor and earned ${q.gold} gold and ${q.xp} experience.`,when:'Today'}));return `<div class="page-heading"><div><div class="eyebrow">The story so far</div><h1>Adventurer's journal</h1><p>Little moments have a way of becoming legends.</p></div><button class="button-outline" data-view="home">← &nbsp;Back to realm</button></div><div class="journal-layout"><section class="card"><div class="section-heading"><div><h3>Recent chapters</h3><div class="subheading">Your deeds and days in Hearthvale</div></div></div>${deeds.map(d=>`<article class="journal-entry"><time>${esc(d.when)}</time><h4>${esc(d.title)}</h4><p>${esc(d.text)}</p></article>`).join('')}</section><section class="card"><div class="section-heading"><div><h3>Adventurer card</h3><div class="subheading">Your name travels with you</div></div><button class="text-link" data-action="profile">EDIT</button></div><div class="guild-hero" style="margin:0;padding:16px;background:linear-gradient(120deg,#425a45,#728369)"><div class="portrait">${esc((state.name[0]||'M').toUpperCase())}</div><div><div class="eyebrow" style="color:#e3cb9c">${esc(state.city)} RESIDENT</div><h2 style="font-size:20px">${esc(state.name)}</h2><p>Level ${state.level} ${esc(state.className)}</p></div></div><p style="font-size:11px;line-height:1.6;color:#7f8175;margin:14px 0">${esc(state.bio)}</p><div class="guild-footer"><span>Rank <b>${rankName()}</b></span><span>${state.influence} influence</span></div></section></div>`}
function showModal(title,subtitle,body,actions=''){const layer=document.getElementById('modal-layer');layer.innerHTML=`<section class="modal" role="dialog" aria-modal="true"><div class="modal-head"><div><h2>${title}</h2><p>${subtitle}</p></div><button class="close-modal" data-action="close-modal" aria-label="Close">×</button></div>${body}${actions}</section>`;layer.hidden=false;layer.querySelector('input,textarea,button')?.focus()}
function closeModal(){const l=document.getElementById('modal-layer');l.hidden=true;l.innerHTML=''}
function profileModal(){showModal('Your character','A little about the adventurer behind the story.',`<form id="profile-form"><label class="form-label">Character name</label><input class="form-control" name="name" maxlength="18" required value="${esc(state.name)}"><label class="form-label">Choose your class</label><div class="class-options">${[['Ranger','➶'],['Mage','✧'],['Knight','⚔'],['Bard','♫'],['Druid','❋'],['Rogue','◈']].map(([n,i])=>`<button type="button" class="class-option ${state.className===n?'selected':''}" data-class="${n}"><span>${i}</span>${n}</button>`).join('')}</div><input type="hidden" name="className" value="${esc(state.className)}"><label class="form-label">Character introduction</label><textarea class="form-control" name="bio" maxlength="120" rows="3" placeholder="What might a stranger learn about you?">${esc(state.bio)}</textarea><div class="modal-actions"><button type="button" class="button-outline" data-action="close-modal">Cancel</button><button class="button-primary">Save character</button></div></form>`)}
function actionModal(action){if(action==='guild-join'){showModal('Find a fellowship','Every guild card opens a new chapter.',`<form id="guild-form"><label class="form-label">Choose a guild</label><select class="form-control" name="guild"><option>The Lantern Wardens</option><option>Greenbriar Circle</option><option>Freefolk Adventurers</option><option>Start a new guild…</option></select><label class="form-label">Your guild card inscription</label><input class="form-control" name="inscription" maxlength="48" placeholder="A few words your new friends should know"></form>`,`<div class="modal-actions"><button class="button-outline" data-action="close-modal">Maybe later</button><button class="button-primary" data-action="confirm-guild">Join fellowship</button></div>`);return}
if(action==='guild-card'){showModal('Guild card',state.guild||'Unaffiliated adventurer',`<div class="card" style="background:linear-gradient(135deg,#354a3a,#63745b);color:white;border:0;padding:20px"><div class="eyebrow" style="color:#e4c990">✦ &nbsp;HEARTHVALE GUILD REGISTRY</div><h2 style="font:600 24px Spectral,serif;margin:12px 0 2px">${esc(state.guild||'Free Adventurer')}</h2><div style="font-size:11px;color:#e3e5d8">${esc(state.name)} · ${esc(state.guildRole||'Independent')} · ${esc(state.className)}</div><div style="border-top:1px solid #87917f;margin-top:18px;padding-top:12px;font-size:10px;color:#e1d7bc">${state.influence} renown &nbsp;·&nbsp; ${rankName()} rank &nbsp;·&nbsp; Member since Emberfall</div></div><p style="font-size:10px;color:#818275;line-height:1.6">Your guild card is your introduction across the Free Realms. It is earned through deeds, not coin.</p>`,`<div class="modal-actions"><button class="button-outline" data-action="close-modal">Close card</button><button class="button-primary" data-action="guild-share">Copy card details</button></div>`);return}
if(action==='run-candidate'){showModal('Stand for Alderbrook','A mayor serves every voice in town.',`<form id="candidate-form"><label class="form-label">Your campaign promise</label><textarea class="form-control" name="pledge" rows="3" maxlength="120" placeholder="What would you work toward?" required></textarea></form>`,`<div class="modal-actions"><button class="button-outline" data-action="close-modal">Not yet</button><button class="button-primary" data-action="confirm-candidate">Join the ballot</button></div>`);return}
if(action==='volunteer'){showModal('Lend a hand','The town notices who shows up.',`<div class="position-grid"><div class="position-tile"><span>⚖</span><strong>River warden</strong><small>Walk the riverside paths</small></div><div class="position-tile"><span>✧</span><strong>Market steward</strong><small>Help neighbors find a stall</small></div><div class="position-tile"><span>♧</span><strong>Storykeeper</strong><small>Welcome newcomers at the inn</small></div><div class="position-tile"><span>☼</span><strong>Spring market</strong><small>Set up stalls on market day</small></div></div>`,`<div class="modal-actions"><button class="button-outline" data-action="close-modal">Maybe later</button><button class="button-primary" data-action="confirm-volunteer">Volunteer</button></div>`);return}
if(action==='chat-help'){showModal('Roleplay, kindly','A few gentle guidelines for the common room.',`<div style="font-size:11px;line-height:1.8;color:#687064"><p><b>Stay in character.</b> Write what your adventurer says or does, and leave room for others to respond.</p><p><b>Share the story.</b> Avoid deciding another character's actions for them; ask before introducing big changes.</p><p><b>Keep it welcoming.</b> Respect boundaries, be kind, and use out-of-character notes when needed.</p><p style="color:#9a8b6d">This preview keeps your messages on this device. Shared online play needs a connected game server.</p></div>`,`<div class="modal-actions"><button class="button-primary" data-action="close-modal">Understood</button></div>`);return}
if(action==='notifications'){showModal('A note from Hearthvale','Fresh news for your adventurer.',`<div class="journal-entry"><time>JUST NOW</time><h4>The spring market is around the corner</h4><p>Neighbors are gathering hands and stories for a lively market day.</p></div><div class="journal-entry"><time>THIS MORNING</time><h4>Your guild has a place for you</h4><p>The Lantern Wardens left your guild card active at the hall.</p></div>`,`<div class="modal-actions"><button class="button-primary" data-action="close-modal">Lovely</button></div>`)}}
function toast(msg){const stack=document.getElementById('toasts'),el=document.createElement('div');el.className='toast';el.innerHTML=msg;stack.appendChild(el);setTimeout(()=>el.remove(),3000)}
function completeQuest(id){const q=quests.find(q=>q.id===id);if(!q||state.completed.includes(id))return;state.completed.push(id);state.gold+=q.gold;state.xp+=q.xp;state.influence+=2;while(state.xp>=100){state.xp-=100;state.level++;toast(`✨ Level up! You are now level <b>${state.level}</b>.`)}state.journal.unshift({title:q.title,text:`You helped a neighbor and earned ${q.gold} gold and ${q.xp} experience.`,when:'Today'});save();render();toast(`Quest complete: <b>+${q.gold} gold</b> · +${q.xp} XP`)}
function bindChat(){const form=document.getElementById('chat-form');if(!form)return;form.addEventListener('submit',e=>{e.preventDefault();const input=form.elements.message;const text=input.value.trim();if(!text)return;if(!state.messages.length)state.messages=defaultMessages();state.messages.push({name:state.name,color:'#e4cda2',text,time:'now'});if(state.messages.length>20)state.messages=state.messages.slice(-20);save();render();document.getElementById('chat-feed').scrollTop=99999;document.querySelector('#chat-form input').focus()})}

